CREATE TABLE dbo.test_purchase_fx_scope(id int PRIMARY KEY CHECK(id=1),product_id bigint NOT NULL CHECK(product_id=301986),supplier_id bigint NOT NULL CHECK(supplier_id=13373),unit nvarchar(20) NOT NULL CHECK(unit=N'ADET'),unit_factor decimal(18,4) NOT NULL CHECK(unit_factor=1),warehouse nvarchar(100) NOT NULL CHECK(warehouse=N'TEST-DAILY-WH'),document_date date NOT NULL CHECK(document_date=CONVERT(date,N'2026-10-04')),max_quantity int NOT NULL CHECK(max_quantity=5),max_amount_try decimal(18,4) NOT NULL CHECK(max_amount_try=200));
CREATE TABLE dbo.test_purchase_fx_rates(id int PRIMARY KEY,currency nvarchar(3) NOT NULL UNIQUE CHECK(currency IN(N'TRY',N'USD',N'EUR')),rate_exact decimal(18,8) NOT NULL CHECK(rate_exact>0),source nvarchar(50) NOT NULL CHECK(source=N'synthetic-test'),source_id nvarchar(80) NOT NULL UNIQUE,as_of date NOT NULL CHECK(as_of=CONVERT(date,N'2026-10-04')),version int NOT NULL CHECK(version=1),hash char(64) NOT NULL);
CREATE TABLE dbo.test_purchase_fx_sources(currency nvarchar(3) PRIMARY KEY CHECK(currency IN(N'USD',N'EUR')),origin_product_id bigint NOT NULL,origin_price_id bigint NOT NULL UNIQUE,origin_product_source_key nvarchar(250) NOT NULL,origin_price_source_key nvarchar(400) NOT NULL,run_id nvarchar(80) NOT NULL,source_hash char(64) NOT NULL,plan_hash char(64) NOT NULL,bindings_hash char(64) NOT NULL,source_as_of date NOT NULL,price_exact decimal(28,8) NOT NULL CHECK(price_exact>0),native_price decimal(18,4) NOT NULL CHECK(native_price>0),unit nvarchar(20) NOT NULL CHECK(unit=N'ADET'),unit_factor decimal(28,8) NOT NULL CHECK(unit_factor=1),main_unit_source_id bigint NOT NULL,product_binding_hash char(64) NOT NULL,price_binding_hash char(64) NOT NULL,native_price_row_hash char(64) NOT NULL);
CREATE TABLE dbo.test_purchase_fx_intents(id bigint IDENTITY PRIMARY KEY,request_id nvarchar(64) NOT NULL UNIQUE,actor_id bigint NOT NULL CHECK(actor_id=16),receipt_id bigint NULL REFERENCES dbo.test_daily_drafts(id),invoice_id bigint NULL REFERENCES dbo.purchase_invoices(id),status nvarchar(20) NOT NULL CHECK(status IN(N'quoted',N'receiving',N'received',N'registered',N'linked',N'cancelled',N'rejected')),origin_product_id bigint NOT NULL,origin_price_id bigint NOT NULL,origin_product_source_key nvarchar(250) NOT NULL,origin_price_source_key nvarchar(400) NOT NULL,run_id nvarchar(80) NOT NULL,source_hash char(64) NOT NULL,plan_hash char(64) NOT NULL,bindings_hash char(64) NOT NULL,source_as_of date NOT NULL,price_exact decimal(28,8) NOT NULL,native_price decimal(18,4) NOT NULL CHECK(native_price>0),currency nvarchar(3) NOT NULL REFERENCES dbo.test_purchase_fx_sources(currency),quantity decimal(18,3) NOT NULL CHECK(quantity BETWEEN 1 AND 5 AND quantity=FLOOR(quantity)),unit nvarchar(20) NOT NULL CHECK(unit=N'ADET'),unit_factor decimal(18,4) NOT NULL CHECK(unit_factor=1),document_rate_id int NOT NULL REFERENCES dbo.test_purchase_fx_rates(id),account_rate_id int NOT NULL REFERENCES dbo.test_purchase_fx_rates(id),document_rate decimal(18,8) NOT NULL,account_rate decimal(18,8) NOT NULL CHECK(account_rate=1),document_total decimal(18,4) NOT NULL CHECK(document_total>0),account_total decimal(18,4) NOT NULL CHECK(account_total>0),amount_try decimal(18,4) NOT NULL CHECK(amount_try>0 AND amount_try<=200),payload_hash char(64) NOT NULL,document_no nvarchar(30) NOT NULL UNIQUE,document_date date NOT NULL,stock_before decimal(18,3) NULL,cost_before decimal(18,4) NULL,stock_after decimal(18,3) NULL,cost_after decimal(18,4) NULL);
CREATE UNIQUE INDEX UX_c03_receipt ON dbo.test_purchase_fx_intents(receipt_id) WHERE receipt_id IS NOT NULL;
CREATE UNIQUE INDEX UX_c03_invoice ON dbo.test_purchase_fx_intents(invoice_id) WHERE invoice_id IS NOT NULL;
CREATE TABLE dbo.test_purchase_fx_requests(request_id nvarchar(64) PRIMARY KEY,payload_hash char(64) NOT NULL,actor_id bigint NOT NULL CHECK(actor_id=16),operation nvarchar(30) NOT NULL CHECK(operation IN(N'quote_create',N'receipt_accept',N'receipt_reject',N'draft_create',N'draft_finalize',N'draft_cancel')),entity_id bigint NOT NULL,response_json nvarchar(max) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.test_purchase_fx_guard_manifest(name sysname PRIMARY KEY,definition_hash char(64) NOT NULL);
INSERT dbo.test_purchase_fx_scope VALUES(1,301986,13373,N'ADET',1,N'TEST-DAILY-WH',N'2026-10-04',5,200);
INSERT dbo.test_purchase_fx_rates SELECT id,currency,rate_exact,N'synthetic-test',N'C03-FX-20261004-'+currency,N'2026-10-04',1,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT(N'C03-FX-20261004|',currency,N'|',CONVERT(varchar(40),rate_exact))),2) FROM (VALUES(1,N'TRY',CAST(1 AS decimal(18,8))),(2,N'USD',CAST(40 AS decimal(18,8))),(3,N'EUR',CAST(45 AS decimal(18,8)))) x(id,currency,rate_exact);

INSERT dbo.test_purchase_fx_sources SELECT TOP(1) v.currency_code,v.product_id,v.price_id,v.product_source_key,v.price_source_key,N'VEGA-OPENING-TEST-20261004-06',m.source_hash,m.plan_hash,m.bindings_hash,N'2026-09-30',v.price_exact,CAST(v.price_exact AS decimal(18,4)),N'ADET',1,b.main_unit_source_id,b.binding_hash,v.binding_hash,v.native_row_hash FROM erp_migration.accepted_price_values v JOIN erp_migration.accepted_price_products b ON b.product_id=v.product_id JOIN dbo.products p ON p.id=b.product_id JOIN dbo.product_prices n ON n.id=v.price_id AND n.product_id=v.product_id JOIN erp_migration.records r ON r.run_id=N'VEGA-OPENING-TEST-20261004-06' AND r.entity=N'products' AND r.source_key=b.product_source_key CROSS JOIN erp_migration.accepted_price_manifest m JOIN dbo.test_purchase_fx_rates fx ON fx.currency=v.currency_code WHERE m.run_id=N'VEGA-OPENING-TEST-20261004-06' AND m.sealed=1 AND v.currency_code=N'USD' AND v.price_type=N'purchase' AND v.price_tier=0 AND v.source_unit_id IS NULL AND v.currency_code IN(N'USD',N'EUR') AND v.price_exact>0 AND ROUND(v.price_exact,4)>0 AND b.unit=N'ADET' AND p.unit=N'ADET' AND p.is_active=1 AND p.is_deleted=0 AND p.stock_code=b.stock_code AND p.name=b.product_name AND p.source_record_key=b.native_source_key AND r.payload_hash=b.stage_payload_hash AND CONVERT(varchar(64),HASHBYTES('SHA2_256',r.payload_json),2)=b.stage_sql_hash AND JSON_VALUE(JSON_VALUE(r.payload_json,'$.source_payload_json'),'$.unitStatus')=N'VERIFIED_ADET_FACTOR_1' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(JSON_VALUE(r.payload_json,'$.source_payload_json'),'$.unitFactor'))=1 AND TRY_CONVERT(bigint,JSON_VALUE(JSON_VALUE(r.payload_json,'$.source_payload_json'),'$.mainUnitSourceId'))=b.main_unit_source_id AND n.price=v.price_exact AND n.price_type=v.price_type AND n.price_tier=v.price_tier AND n.currency_code=v.currency_code AND n.source_unit_id IS NULL AND CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT n.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2)=v.native_row_hash AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WHERE a.product_id=p.id)=1 AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WHERE a.source_product_id=TRY_CONVERT(int,b.source_id) AND a.product_id=p.id)=1 AND NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N'product' AND h.native_id=p.id) AND CAST(v.price_exact AS decimal(18,4))*fx.rate_exact<=200 ORDER BY v.price_id;
IF NOT EXISTS(SELECT 1 FROM dbo.test_purchase_fx_sources WHERE currency=N'USD') THROW 51072,'C03_ELIGIBLE_ACCEPTED_COPY_MISSING',1;

