),2)=v.native_row_hash AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WHERE a.product_id=p.id)=1 AND (SELECT COUNT(*) FROM dbo.product_source_aliases a WHERE a.source_product_id=TRY_CONVERT(int,b.source_id) AND a.product_id=p.id)=1 AND NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE h.entity=N'product' AND h.native_id=p.id) AND CAST(v.price_exact AS decimal(18,4))*fx.rate_exact<=200 ORDER BY v.price_id;
IF NOT EXISTS(SELECT 1 FROM dbo.test_purchase_fx_sources WHERE currency=N'EUR') THROW 51072,'C03_ELIGIBLE_ACCEPTED_COPY_MISSING',1;

DECLARE @body nvarchar(max),@unchanged nvarchar(max);

SET @body=CAST(N'CREATE TRIGGER dbo.c03_immutable_test_purchase_fx_scope ON dbo.test_purchase_fx_scope WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF DB_NAME() COLLATE Latin1_General_100_BIN2<>N''MELISA_ERP_SIRKET_TEST_20260929_01'' OR CAST(SERVERPROPERTY(''ServerName'') AS nvarchar(128)) COLLATE Latin1_General_100_BIN2<>N''Semih\MELISADEV'' THROW 51070,''WRONG_TEST_BATCH_TARGET'',1;
IF (SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'')<>''9AE41CA1AB25EE165019AD04DBD9A6FB4E5B7190F027E0A07A87FB03D698379E'' THROW 51072,''C03_PRESERVED_GUARD_DRIFT'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_batch_guard_manifest)<>15 OR EXISTS(SELECT 1 FROM dbo.test_purchase_batch_guard_manifest m LEFT JOIN sys.triggers t ON t.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE t.object_id IS NULL OR t.is_disabled=1 OR m.after_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(t.object_id)),2)) THROW 51072,''C03_ORIGINAL_15_GUARD_DRIFT'',1;
IF (SELECT COUNT(*) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' AND is_disabled=0 AND OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger'')=1)<>37 THROW 51072,''C03_QUARANTINE_FIRST_DRIFT'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_manifest WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND sealed=1 AND seal_hash=''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' AND source_rows=176 AND native_holds=172 AND not_present=4) THROW 51072,''C03_QUARANTINE_SEAL_DRIFT'',1;
