IF NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope d JOIN dbo.products p ON p.id=d.product_id JOIN dbo.suppliers s ON s.id=d.supplier_id WHERE d.flow=N''purchase'' AND p.id=301986 AND s.id=13373 AND p.stock_code=N''TEST-DAILY-PURCHASE'' AND p.unit=N''ADET'' AND p.currency_code=N''TRY'' AND p.supplier_id=s.id AND p.is_active=1 AND p.is_deleted=0 AND s.supplier_code=N''TEST-DAILY-PUR-S'' AND s.currency_code=N''TRY'' AND s.is_active=1 AND s.is_deleted=0) OR EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds WHERE (entity=N''product'' AND native_id=301986) OR (entity=N''supplier'' AND native_id=13373)) THROW 51072,''C03_NATIVE_FIXTURE_DRIFT'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_fx_guard_manifest)<>17 OR EXISTS(SELECT 1 FROM dbo.test_purchase_fx_guard_manifest m LEFT JOIN sys.objects o ON o.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE o.object_id IS NULL OR OBJECT_DEFINITION(o.object_id) IS NULL OR m.definition_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(o.object_id)),2) OR (o.type=N''TR'' AND COALESCE(OBJECTPROPERTY(o.object_id,''ExecIsTriggerDisabled''),1)<>0)) THROW 51072,''C03_OPERATIONAL_GUARD_DRIFT'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_fx_scope)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.test_purchase_fx_scope WHERE id=1 AND product_id=301986 AND supplier_id=13373 AND unit=N''ADET'' AND unit_factor=1 AND warehouse=N''TEST-DAILY-WH'' AND document_date=CONVERT(date,N''2026-10-04'') AND max_quantity=5 AND max_amount_try=200) THROW 51072,''C03_SCOPE_DRIFT'',1;
