IF (SELECT COUNT(*) FROM dbo.test_purchase_fx_sources)<>2 OR EXISTS(SELECT 1 FROM dbo.test_purchase_fx_sources s WHERE NOT EXISTS(SELECT 1 FROM erp_migration.accepted_price_values v JOIN erp_migration.accepted_price_products b ON b.product_id=v.product_id WHERE v.price_id=s.origin_price_id AND v.product_id=s.origin_product_id AND v.product_source_key=s.origin_product_source_key AND v.price_source_key=s.origin_price_source_key AND v.price_type=N''purchase'' AND v.currency_code=s.currency AND v.price_exact=s.price_exact AND CAST(v.price_exact AS decimal(18,4))=s.native_price AND b.unit=s.unit AND s.unit=N''ADET'' AND s.unit_factor=1 AND b.main_unit_source_id=s.main_unit_source_id AND b.binding_hash=s.product_binding_hash AND v.binding_hash=s.price_binding_hash AND v.native_row_hash=s.native_price_row_hash AND s.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND s.source_as_of=CONVERT(date,N''2026-09-30'') AND s.source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND s.plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND s.bindings_hash=''5842be926d493c8973566fd922ef840d9fe6f7cecd9d83f17f506be5aa3fbd72'')) THROW 51072,''C03_COPY_SOURCE_DRIFT'',1;
IF EXISTS(SELECT 1 FROM inserted) OR EXISTS(SELECT 1 FROM deleted) THROW 51072,''C03_EXACT_QUOTE_LINEAGE_REQUIRED'',1;
END;' AS nvarchar(max));

